def singleL (n : ℕ) : Y →L[𝕜] SchauderSum b hb Y :=
  LinearMap.mkContinuous
    { toFun := single n
      map_add' := by intro y z; ext i; by_cases hi : i = n <;> simp [single_apply, hi]
      map_smul' := by intro c y; ext i; by_cases hi : i = n <;> simp [single_apply, hi] }
    1 (fun y => by simp)

